"""Presentation and verified external-demo transition; synthetic browser-local records only."""
import importlib.util,unittest
from pathlib import Path
spec=importlib.util.spec_from_file_location('prior',Path(__file__).with_name('qa-consolidated.py'));base=importlib.util.module_from_spec(spec);spec.loader.exec_module(base)
class Polish(base.Consolidated):
 def test_polish_01_primary_locked_demo_is_external_and_local_reference_is_preserved(self):
  self.basic();p=self.page;before=self.state();p.goto(base.base.BASE+'/locked-in-demo');link=p.get_by_role('link',name='Open Interactive LockedIn Demo',exact=False);self.assertEqual(link.get_attribute('href'),'https://soccercenter.org/locked-in/index.html');self.assertEqual(link.get_attribute('target'),'_blank');self.assertIn('noopener',link.get_attribute('rel'));self.assertIn('noreferrer',link.get_attribute('rel'));self.assertFalse(p.locator('#lockedin-workflow').is_visible());self.assertGreaterEqual(link.bounding_box()['height'],44)
  self.context.route('https://soccercenter.org/locked-in/index.html',lambda route:route.fulfill(status=200,content_type='text/html',body='<title>Transition test stub</title><p>External tab test; not the live SC demo.</p>'))
  with self.context.expect_page() as popup:link.click()
  external=popup.value;external.wait_for_load_state();self.assertEqual(external.url,'https://soccercenter.org/locked-in/index.html');self.assertEqual(p.url,base.base.BASE+'/locked-in-demo');external.close();self.assertEqual(self.state(),before);p.locator('#ap-local-demo-reference>summary').click();p.wait_for_selector('#lockedin-workflow input');self.assertTrue(p.get_by_role('button',name='Simulate NSID result',exact=True).is_visible())
 def test_polish_02_four_sport_heroes_and_full_directories_respond(self):
  p=self.page
  for sport in ['lacrosse','volleyball','basketball','swimming']:
   counts=[]
   for width,height in [(1440,900),(810,1080),(390,844)]:
    p.set_viewport_size({'width':width,'height':height});p.goto(base.base.BASE+'/sports/'+sport);p.wait_for_selector('.directory-records>article');p.wait_for_function('()=>document.querySelector(".directory-photo img").complete');image=p.locator('.directory-photo img');self.assertGreater(image.evaluate('(e)=>e.naturalWidth'),0);self.assertIn('/photos/'+sport,image.get_attribute('src'));self.assertFalse(p.evaluate('document.documentElement.scrollWidth>innerWidth+1'),sport+str(width));counts.append(p.locator('.directory-records>article').count());self.assertEqual(p.locator('.participation-nav').get_by_role('link',name='Sport Home',exact=True).get_attribute('aria-current'),'page');create=p.get_by_role('link',name='Create Your Pathway',exact=True);self.assertIn('sport='+sport,create.get_attribute('href'));self.assertGreaterEqual(create.bounding_box()['height'],44);p.get_by_role('link',name='Explore clubs & programs',exact=False).click();self.assertTrue(p.locator('#sport-directory form').is_visible());self.assertGreaterEqual(p.locator('.sport-news-card').count(),1);self.assertEqual(p.locator('.sport-news-card img').count(),0)
   self.assertEqual(len(set(counts)),1);self.assertGreaterEqual(counts[0],13 if sport=='lacrosse' else 1)
 def test_polish_03_entry_distinguishes_tour_setup_and_existing_dashboard(self):
  self.basic();p=self.page;before=self.state();p.goto(base.base.BASE+'/my-ap');p.wait_for_selector('#platform-entry:not([hidden])');entry=p.locator('#platform-entry');self.assertTrue(entry.get_by_role('link',name='Set Up My Family',exact=True).is_visible());self.assertEqual(entry.get_by_role('link',name='Set Up My Family',exact=True).get_attribute('href'),'/siem/setup');entry.get_by_role('button',name='Start Guided Tour',exact=True).click();self.assertTrue(p.locator('#siem-tour').evaluate('(e)=>e.open'));self.assertEqual(p.locator('#platform-scenario').input_value(),'family');p.locator('#siem-tour').get_by_role('button',name='Next',exact=True).click();p.locator('#siem-tour').get_by_role('button',name='Back',exact=True).click();self.assertIn('Step 1 of 6',p.locator('#siem-tour').inner_text());p.locator('#siem-tour').get_by_role('button',name='Skip',exact=True).click();entry.get_by_role('button',name='Explore Dashboard',exact=True).click();self.assertFalse(entry.is_visible());self.assertTrue(p.locator('.ap-tour-discover').is_visible());self.assertEqual(self.state(),before)
 def test_polish_04_direct_calendar_preserves_local_family_and_tour_is_fictional(self):
  athlete=self.basic();p=self.page;before=self.state();p.goto(base.base.BASE+'/my-ap?scenario=local&section=calendar');p.wait_for_selector('#platform-calendar');self.assertFalse(p.locator('#platform-entry').is_visible());p.get_by_role('button',name='Start Guided Tour',exact=True).click();self.assertEqual(p.locator('#platform-scenario').input_value(),'family');p.locator('#siem-tour').get_by_role('button',name='Skip',exact=True).click();self.assertEqual(self.state(),before);self.assertEqual(self.state()['active'],athlete)
 def test_polish_05_ipad_readability_focus_and_evidence_disclosure(self):
  p=self.page;p.goto(base.base.BASE+'/my-ap?scenario=family&mode=command');p.wait_for_selector('.ap-feed');heading=p.locator('#platform-calendar .ap-activity h3').first;self.assertGreaterEqual(heading.evaluate('(e)=>parseFloat(getComputedStyle(e).fontSize)'),16);self.assertGreaterEqual(p.locator('.ap-tour-discover').bounding_box()['height'],44);p.locator('.ap-tour-discover').focus();self.assertNotEqual(p.locator('.ap-tour-discover').evaluate('(e)=>getComputedStyle(e).outlineStyle'),'none');self.assertFalse(p.locator('.ap-action-evidence').first.evaluate('(e)=>e.open'));p.locator('.ap-action-evidence>summary').first.click();self.assertIn('DEMO',p.locator('.ap-action-evidence').first.inner_text())
  for width,height in [(1440,900),(1024,768),(810,1080),(390,844)]:
   p.set_viewport_size({'width':width,'height':height});p.evaluate('()=>new Promise(requestAnimationFrame)');self.assertFalse(p.evaluate('document.documentElement.scrollWidth>innerWidth+1'))
 def test_polish_06_parent_navigation_marks_the_current_section(self):
  self.basic();p=self.page;before=self.state();p.goto(base.base.BASE+'/my-pathway?view=family');p.wait_for_selector('.family-athlete-card');nav=p.get_by_role('navigation',name='Parent workspace',exact=True);self.assertEqual(nav.get_by_role('link',name='Players',exact=True).get_attribute('aria-current'),'page');nav.get_by_role('link',name='Saved',exact=True).click();self.assertEqual(nav.get_by_role('link',name='Saved',exact=True).get_attribute('aria-current'),'page');self.assertIsNone(nav.get_by_role('link',name='Players',exact=True).get_attribute('aria-current'));p.reload();p.wait_for_selector('.family-athlete-card');self.assertEqual(p.get_by_role('navigation',name='Parent workspace',exact=True).get_by_role('link',name='Saved',exact=True).get_attribute('aria-current'),'page');self.assertEqual(self.state(),before)
for name in list(vars(base.Consolidated)):
 if name.startswith('test_'):setattr(Polish,name,None)
if __name__=='__main__':unittest.main(verbosity=2)
